import { useMemo, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ArrowUp, MessageSquareText, Search, ShieldCheck } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { operationsRepository } from "@/services/supabase/operations";
import { useAuth } from "@/features/auth/auth-context";
import { usePageMeta } from "@/hooks/usePageMeta";

export default function OpsInboxPage() {
  usePageMeta("Messagerie opérations", "Répondez aux clients dans la conversation rattachée à chaque projet.");
  const { user } = useAuth();
  const client = useQueryClient();
  const { data = [], isLoading, error } = useQuery({ queryKey: ["ops", "inbox"], queryFn: operationsRepository.getInbox, refetchInterval: 20_000 });
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [body, setBody] = useState("");
  const [internal, setInternal] = useState(false);
  const filtered = useMemo(() => data.filter((item) => `${item.project?.display_name ?? "Projet"} ${item.messages.at(-1)?.body ?? ""}`.toLocaleLowerCase("fr-FR").includes(query.toLocaleLowerCase("fr-FR"))), [data, query]);
  const selected = data.find((item) => item.id === selectedId) ?? data[0] ?? null;
  const mutation = useMutation({ mutationFn: () => selected ? operationsRepository.sendMessage(selected.id, body, internal) : Promise.resolve(), onSuccess: async () => { setBody(""); setInternal(false); await client.invalidateQueries({ queryKey: ["ops", "inbox"] }); } });
  return <div className="mx-auto max-w-[1480px] space-y-5"><section className="hero-grid surface-noise rounded-[32px] bg-[var(--night)] p-7 text-white sm:p-9"><span className="grid size-13 place-items-center rounded-[18px] bg-[var(--mint)] text-[color:var(--ink)]"><MessageSquareText className="size-5" /></span><h1 className="mt-6 text-4xl font-semibold tracking-[-.055em] sm:text-5xl">Boîte de réception projets</h1><p className="mt-4 max-w-2xl text-sm leading-7 text-white/72">Chaque réponse reste liée au projet. Les notes internes sont filtrées par les permissions et ne sont jamais montrées au client.</p></section>{error ? <Card className="p-5 text-sm text-[color:var(--blue)]">{error instanceof Error ? error.message : "Chargement impossible"}</Card> : null}<Card className="grid min-h-[680px] overflow-hidden lg:grid-cols-[330px_1fr]"><aside className="border-b border-[var(--line)] bg-[var(--paper)] lg:border-b-0 lg:border-r"><div className="p-4"><label className="flex h-11 items-center gap-2 rounded-full border border-[var(--line)] bg-white px-4 text-sm"><Search className="size-4 text-[color:var(--muted)]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Projet ou message" className="min-w-0 flex-1 bg-transparent outline-none" /></label></div><div className="divide-y divide-[var(--line)]">{filtered.map((item) => { const last = item.messages.at(-1); return <button key={item.id} onClick={() => setSelectedId(item.id)} className={`w-full p-4 text-left transition ${selectedId === item.id ? "bg-white" : "hover:bg-white/60"}`}><p className="font-semibold">{item.project?.display_name ?? "Projet"}</p><p className="mt-1 truncate text-xs text-[color:var(--muted)]">{last?.body ?? "Aucun message"}</p><p className="mt-2 text-[10px] font-semibold text-[color:var(--muted)]">{last ? new Date(last.created_at).toLocaleString("fr-FR") : "Conversation prête"}</p></button>; })}{!isLoading && filtered.length === 0 ? <p className="p-8 text-center text-sm text-[color:var(--muted)]">Aucune conversation accessible.</p> : null}</div></aside><div className="flex min-h-0 flex-col">{selected ? <><header className="border-b border-[var(--line)] px-5 py-4"><p className="font-semibold">{selected.project?.display_name ?? "Projet"}</p><p className="mt-1 text-xs text-[color:var(--muted)]">Conversation {selected.id.slice(0, 8)}</p></header><div className="flex-1 space-y-4 overflow-y-auto bg-[var(--paper)] p-5 sm:p-7">{selected.messages.map((message) => { const own = message.sender_user_id === user?.id; return <div key={message.id} className={`flex ${own ? "justify-end" : "justify-start"}`}><div className={`max-w-[82%] rounded-[20px] px-4 py-3 text-sm leading-6 ${message.internal_only ? "border border-[var(--blue)]/20 bg-[var(--blue)]/8" : own ? "bg-[var(--ink)] text-white" : "bg-white"}`}><p className="whitespace-pre-wrap">{message.body}</p><p className={`mt-2 text-[10px] ${own && !message.internal_only ? "text-white/72" : "text-[color:var(--muted)]"}`}>{message.internal_only ? "Note interne · " : ""}{new Date(message.created_at).toLocaleString("fr-FR")}</p></div></div>; })}</div><div className="border-t border-[var(--line)] bg-white p-4"><label className="mb-3 flex items-center gap-2 text-xs font-semibold text-[color:var(--muted)]"><input type="checkbox" checked={internal} onChange={(event) => setInternal(event.target.checked)} className="size-4 accent-[var(--blue)]" /><ShieldCheck className="size-3.5" />Note interne — invisible pour le client</label><div className="flex items-end gap-2 rounded-[20px] border border-[var(--line)] bg-[var(--paper)] p-2"><textarea rows={2} value={body} onChange={(event) => setBody(event.target.value)} placeholder={internal ? "Ajouter une note interne…" : "Répondre au client…"} className="max-h-36 flex-1 resize-none bg-transparent px-2 py-1 text-sm outline-none" /><button type="button" onClick={() => mutation.mutate()} disabled={!body.trim() || mutation.isPending} className="grid size-11 shrink-0 place-items-center rounded-full bg-[var(--ink)] text-white disabled:opacity-35" aria-label="Envoyer"><ArrowUp className="size-4" /></button></div>{mutation.error ? <p className="mt-2 text-xs text-[color:var(--blue)]">{mutation.error instanceof Error ? mutation.error.message : "Envoi impossible"}</p> : null}</div></> : <div className="grid flex-1 place-items-center p-8 text-sm text-[color:var(--muted)]">Sélectionnez une conversation.</div>}</div></Card></div>;
}
